              icon: <CloudServerOutlined />,
              color: COLOR.purple,
              path: `/k8s/${clusterId}/deployments`,
            },
            {
              label: 'CPU 使用率',
              value: overview.meta?.metrics_available === false ? '--' : `${s.cpu.used_percent}%`,
              sub:
                overview.meta?.metrics_available === false
