                  : `内存 ${s.memory.used_percent}%`,
              icon: <DashboardOutlined />,
              color:
                overview.meta?.metrics_available === false
                  ? COLOR.idle
                  : s.cpu.used_percent >= 80
                    ? COLOR.critical
                    : s.cpu.used_percent >= 70
                      ? COLOR.warning
                      : COLOR.healthy,
