                      justifyContent: 'center',
                      color: kpi.color,
                      fontSize: 18,
                    }}
                  >
                    {kpi.icon}
                  </div>
                  <div style={{ minWidth: 0, paddingLeft: 2 }}>
                    <Text type="secondary" style={{ fontSize: 11 }}>
                      {kpi.label}
