              <Col span={14}>
                {healthBreakdown.map((item) => (
                  <div key={item.key} style={{ marginBottom: 10 }}>
                    <Row justify="space-between" style={{ marginBottom: 2 }}>
                      <Text strong style={{ fontSize: 12 }}>
                        {item.label}
