      {/* 详情抽屉 */}
      <Drawer
        title={`CronJob 详情 - ${detailCronJob?.name}`}
        open={!!detailCronJob}
        onClose={() => setDetailCronJob(null)}
        width={720}
        destroyOnClose
      >
        {detailCronJob && (
          <Tabs
            defaultActiveKey="overview"
